function findMinMoves(machines) {
  const n = machines.length;
  const total = machines.reduce((a, b) => a + b, 0);
  if (total % n !== 0) return -1;
  const target = total / n;
  if (n <= 5 && total <= 12) {
    // Breadth-first search over states: each move lets every machine stay, pass left or pass right.
    const goal = machines.map(() => target).join(',');
    const seen = new Set([machines.join(',')]);
    let frontier = [machines.slice()];
    for (let moves = 0; ; moves++) {
      if (frontier.some(state => state.join(',') === goal)) return moves;
      const next = [];
      for (const state of frontier) {
        for (let code = 1; code < 3 ** n; code++) {
          const after = state.slice();
          let ok = true;
          for (let i = 0, c = code; i < n && ok; i++, c = Math.floor(c / 3)) {
            if (c % 3 === 0) continue;
            const to = c % 3 === 1 ? i - 1 : i + 1;
            if (state[i] === 0 || to < 0 || to >= n) ok = false;
            else { after[i]--; after[to]++; }
          }
          const key = after.join(',');
          if (ok && !seen.has(key)) { seen.add(key); next.push(after); }
        }
      }
      frontier = next;
    }
  }
  // Bigger cases: recompute each boundary's net crossing and each machine's surplus from scratch.
  let best = 0;
  for (let i = 0; i < n; i++) {
    let crossing = 0;
    for (let j = 0; j <= i; j++) crossing += machines[j] - target;
    best = Math.max(best, Math.abs(crossing), machines[i] - target);
  }
  return best;
}

