function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 5);
    if (rand() < 0.25) return [Array.from({ length: n }, () => int(0, 3))];
    // Usually a balanced total: scatter target * n dresses over the machines.
    const target = int(0, Math.floor(10 / n));
    const machines = new Array(n).fill(0);
    for (let k = 0; k < target * n; k++) machines[rand() < 0.4 ? 0 : int(0, n - 1)]++;
    if (rand() < 0.5) machines.reverse();
    return [machines];
  }
  const n = 2000;
  const mode = int(0, 2);
  let machines;
  if (mode === 0) machines = Array.from({ length: n }, () => int(0, 100000));
  else if (mode === 1) machines = Array.from({ length: n }, (_, i) => (i < n / 2 ? int(60000, 100000) : int(0, 40000)));
  else { machines = new Array(n).fill(0); machines[int(0, n - 1)] = n * int(1, 50); }
  // Make the total divisible by n so the answer is not -1.
  let remainder = machines.reduce((a, b) => a + b, 0) % n;
  for (let i = 0; remainder > 0; i++) {
    const take = Math.min(remainder, machines[i]);
    machines[i] -= take;
    remainder -= take;
  }
  return [machines];
}
